    static List<List<Object>> rows(SQLiteDatabase db,String q){List<List<Object>> out=new ArrayList<>();try(Cursor c=db.rawQuery(q,null)){while(c.moveToNext()){List<Object> row=new ArrayList<>();for(int i=0;i<c.getColumnCount();i++){int t=c.getType(i);row.add(t==0?null:t==4?Base64.getEncoder().encodeToString(c.getBlob(i)):t==1?c.getLong(i):t==2?c.getDouble(i):c.getString(i));}out.add(row);}}return out;}
    static void budgets(int start){long maxSql=0,maxBind=0,maxRows=0;List<Long> times=new ArrayList<>();for(int i=start;i<SQLiteDatabase.frames.size();i++){Map<String,Object> f=SQLiteDatabase.frames.get(i);if(!f.get("scenario").toString().startsWith("NEW_"))continue;long sql=((Number)f.get("sqlCalls")).longValue(),bind=((Number)f.get("bindBytes")).longValue(),changed=((Number)f.get("totalChangedRowsIncludingTriggersAndAttemptedRollback")).longValue();need(sql<=64,"ALL_SQL_WITH_FENCE_RECEIPTS:"+sql);need(bind<=Math.min(262144L,Runtime.getRuntime().maxMemory()/512),"DYNAMIC_BIND_CAP:"+bind);if(Boolean.TRUE.equals(f.get("committed")))need(((Number)f.get("fenceReads")).longValue()>=2,"BOTH_OWNER_EDGES");for(Object item:(List<?>)f.get("sql")){String q=((Map<?,?>)item).get("sql").toString().toUpperCase(Locale.ROOT);need(!q.matches("(?s)^(CREATE|ALTER|DROP|VACUUM|REINDEX).*"),"BUSINESS_DDL0");}maxSql=Math.max(maxSql,sql);maxBind=Math.max(maxBind,bind);maxRows=Math.max(maxRows,changed);times.add(((Number)f.get("sqlTransactionNanos")).longValue());}Collections.sort(times);Map<String,Object> r=new LinkedHashMap<>();r.put("transactions",times.size());r.put("maxSql",maxSql);r.put("maxBind",maxBind);r.put("maxRowsWithTriggers",maxRows);r.put("p99HostNanos",times.isEmpty()?0:times.get((int)Math.ceil(times.size()*.99)-1));r.put("timingScope","FULL_NAMED_HOST_DENOMINATOR_NOT_ANDROID_SLO");System.out.println("RESULT "+JsonR27.write(r));}
    static void drain(Path path)throws Exception{
        Files.deleteIfExists(path);try(WarmAbiHostR31.World w=new WarmAbiHostR31.World(path,"foundry-su2")){
            SQLiteDatabase.scenario="CONTROLLED_2048_PRESERVATION_INPUT";ModelGenomeSU2 template=FamilyRegistryR26.genome("F11");w.db.beginTransaction();try{w.db.execSQL("INSERT INTO r26_foundry(campaign_id,snapshot_hash,source_through,snapshot,status,created_at,numerical_abi,source_first) VALUES('expired',?,10000,X'','EXPIRED_RETENTION',1,?,1)",new Object[]{StatsR27.sha256("OLD_FROZEN_SOURCE"),ResearchSemanticsGeneratedR967.TRAINING_RULE_SHA256});for(int i=0;i<2048;i++){ModelGenomeSU2 g=template.bindBirth(StatsR27.sha256("CONTROLLED_EXPIRED_SOURCE_"+i),10000);w.db.execSQL("INSERT INTO r26_candidate(campaign_id,policy_hash,canonical_text,cursor,state,state_hash,checkpoint_hash,status,operation) VALUES('expired',?,?,?,?,?,?,'READY','PERSISTENCE_FANOUT_FIXTURE')",new Object[]{g.key(),g.text(),i%2==0?16:0,i%2==0?new byte[]{1,2,3}:null,StatsR27.sha256("OLD_STATE_"+i),StatsR27.sha256("OLD_CHECKPOINT_"+i)});}w.db.setTransactionSuccessful();}finally{w.db.endTransaction();}
            List<List<Object>> original=rows(w.ro,"SELECT "+WarmPublicationR31.COLUMNS+" FROM r26_candidate ORDER BY policy_hash");int start=SQLiteDatabase.frames.size();
            // Real SQLite rollback after at least one prepared operation; all original values survive.
            SQLiteDatabase.scenario="NEW_DRAIN_ROLLBACK";SQLiteDatabase.failOnceSqlPrefix="UPDATE r26_candidate SET status=";boolean refused=false;try{FoundryCampaignR26.step(w.store,()->w.claim,new BudgetTokenSU1(60000,10000000,()->false));}catch(RuntimeException expected){refused=true;}need(refused,"REAL_DRAIN_ROLLBACK");need(original.equals(rows(w.ro,"SELECT "+WarmPublicationR31.COLUMNS+" FROM r26_candidate ORDER BY policy_hash")),"ROLLBACK_ALL_17_ORIGINAL_FIELDS");need(n(w,"SELECT count(*) FROM r30_keep_r26_candidate")==0,"ROLLBACK_ARCHIVE_ALSO_ATOMIC");
            // Prepared source keys fail closed if the source changes before writer admission.
            try(WarmCandidateR26.PreparedPreservationR31 p=WarmCandidateR26.preparePreservationR31(w.ro)){SQLiteDatabase.scenario="CONTROLLED_SOURCE_CHANGE";w.db.execSQL("UPDATE r26_foundry SET snapshot_hash=? WHERE campaign_id='expired'",new Object[]{StatsR27.sha256("COMPETING_SOURCE")});SQLiteDatabase.scenario="NEW_DRAIN_SOURCE_CAS";int changed=w.coordinator.runAtomicWriteOrThrowF01("R31_WARM_SOURCE_CAS",db->{RuntimeCoordinatorR26.requireFence(db,w.claim);int result=WarmCandidateR26.applyPreparedPreservationR31(db,p);RuntimeCoordinatorR26.requireFence(db,w.claim);return result;});need(changed==0,"OLD_PREPARED_SOURCE_NO_CHANGE");w.db.execSQL("UPDATE r26_foundry SET snapshot_hash=? WHERE campaign_id='expired'",new Object[]{StatsR27.sha256("OLD_FROZEN_SOURCE")});}
            RuntimeCoordinatorR26.Claim old=w.claim;try(WarmCandidateR26.PreparedPreservationR31 p=WarmCandidateR26.preparePreservationR31(w.ro)){w.bind("foundry-su2",old.fence+1);SQLiteDatabase.scenario="NEW_DRAIN_LATE_OWNER";refused=false;try{w.coordinator.runAtomicWriteOrThrowF01("R31_WARM_OLD_OWNER",db->{RuntimeCoordinatorR26.requireFence(db,old);WarmCandidateR26.applyPreparedPreservationR31(db,p);RuntimeCoordinatorR26.requireFence(db,old);return 0;});}catch(RuntimeException expected){refused=true;}need(refused,"LATE_OWNER_CANNOT_PRESERVE_OR_DELETE");}
            int chunks=0;for(;;){try(WarmCandidateR26.PreparedPreservationR31 p=WarmCandidateR26.preparePreservationR31(w.ro)){if(p.rows()==0)break;}SQLiteDatabase.scenario="NEW_ACTUAL_FOUNDRY_PREPARED_DRAIN";FoundryCampaignR26.step(w.store,()->w.claim,new BudgetTokenSU1(60000,10000000,()->false));need(++chunks<=256,"FINITE_DRAIN_NO_STARVATION");}
            need(chunks==256,"ALL_2048_ROWS_SERVED_EIGHT_PER_PRODUCER_CALL");need(n(w,"SELECT count(*) FROM r26_candidate WHERE status='WAITING_WARM_FORK'")==1024,"ALL_1024_LEARNED_WEIGHTS_RETAINED");need(n(w,"SELECT count(*) FROM r30_keep_r26_candidate")==1024,"ALL_1024_ORIGINAL_REMOVALS_ARCHIVED");List<List<Object>> all=rows(w.ro,"SELECT "+WarmPublicationR31.COLUMNS+" FROM r26_candidate UNION ALL SELECT "+WarmPublicationR31.COLUMNS+" FROM r30_keep_r26_candidate ORDER BY policy_hash");for(List<Object> row:all)row.set(12,"READY");need(original.equals(all),"EVERY_ORIGINAL_SQL_VALUE_TYPE_AND_BLOB_RETAINED");need(n(w,"SELECT count(*) FROM r26_cohort")==0,"NO_NEW_QUALITY_FROM_PRESERVATION");budgets(start);System.out.println("PASS "+WarmAbiHostR31.assertions+" ACTUAL_FOUNDRY_2048_DRAIN_WITH_ROLLBACK_SOURCE_OWNER");
        }
    }
    static void invariant(WarmAbiHostR31.World w)throws Exception{
        need(n(w,"SELECT count(*) FROM r26_warm_initialization")==1,"COMPLETE_INITIALIZER");need(n(w,"SELECT count(*) FROM r26_candidate WHERE campaign_id='OLD_WARM_PARENT'")==0,"TRANSFERRED_PARENT");need(n(w,"SELECT count(*) FROM r30_keep_r26_candidate WHERE campaign_id='OLD_WARM_PARENT'")==1,"EXACT_COMPLETE_PARENT_ARCHIVE");need(n(w,"SELECT completed FROM r26_work_total WHERE task_id='warm-candidates'")==1,"EXACTLY_ONE_DURABLE_WORK");need(n(w,"SELECT count(*) FROM r26_cohort")==0,"NO_COHORT_OR_ALPHA_TRANSFER");need(n(w,"SELECT count(*) FROM su2_model_genome")==0,"NO_FORMAL_CHAMPION_OR_QUALITY_TRANSFER");
        try(Cursor parent=w.ro.rawQuery("SELECT canonical_text,state,state_hash FROM r30_keep_r26_candidate WHERE campaign_id='OLD_WARM_PARENT'",null);Cursor child=w.ro.rawQuery("SELECT canonical_text,state,state_hash,cursor FROM r26_candidate",null)){need(parent.moveToFirst()&&child.moveToFirst()&&child.getInt(3)==0,"PRIVATE_CURSOR_ZERO");LiveStateR26 old=LiveStateR26.decode(parent.getString(0),CheckpointArtifactsR26.resolve(w.store,parent.getBlob(1)),parent.getString(2));old.onGap();LiveStateR26 now=LiveStateR26.decode(child.getString(0),CheckpointArtifactsR26.resolve(w.store,child.getBlob(1)),child.getString(2));need(Arrays.equals(WarmAbiHostR31.kernel(old.hub.models.values().iterator().next()),WarmAbiHostR31.kernel(now.hub.models.values().iterator().next())),"ALL_KERNEL_OPTIMIZER_BYTES_EQUAL_TO_ORIGINAL_GAP_RESET");}
    }
    static void warm(Path path,String mode)throws Exception{
        boolean resume=mode.equals("resume");if(!resume)Files.deleteIfExists(path);try(WarmAbiHostR31.World w=new WarmAbiHostR31.World(path,"warm-candidates")){if(!resume)WarmAbiHostR31.setupWarm(w);int start=SQLiteDatabase.frames.size();
            SQLiteDatabase.afterFrame=f->{long child=n(w,"SELECT count(*) FROM r26_warm_initialization"),parent=n(w,"SELECT count(*) FROM r26_candidate WHERE campaign_id='OLD_WARM_PARENT'"),work=n(w,"SELECT coalesce(max(completed),0) FROM r26_work_total WHERE task_id='warm-candidates'");need(child==0&&parent==1&&work==0||child==1&&parent==0&&work==1,"NO_CANONICAL_PARTIAL_AFTER_EVERY_PHYSICAL_TX");};
            if(mode.equals("halt")){SQLiteDatabase.afterFrame=f->{need(n(w,"SELECT count(*) FROM r26_warm_initialization")==0,"NO_WARM_VISIBLE_BEFORE_HALT");if(n(w,"SELECT count(*) FROM r31_model_publication WHERE staged_items=expected_items AND status='PREPARING'")>0)Runtime.getRuntime().halt(74);};}
            if(mode.equals("rollback")||mode.equals("source")||mode.equals("late-owner")){SQLiteDatabase.scenario="NEW_WARM_FINAL_ROLLBACK";SQLiteDatabase.failOnceSqlPrefix="INSERT INTO r26_warm_initialization";boolean refused=false;try{WarmCandidateR26.step(w.store,()->w.claim,new BudgetTokenSU1(60000,10000000,()->false));}catch(RuntimeException expected){refused=true;}need(refused,"REAL_FINAL_SQL_ROLLBACK");need(n(w,"SELECT count(*) FROM r26_warm_initialization")==0&&n(w,"SELECT count(*) FROM r26_candidate WHERE campaign_id='OLD_WARM_PARENT'")==1,"NO_FINAL_PARTIAL");long receipts=n(w,"SELECT count(*) FROM r31_commit_receipt");
                if(!mode.equals("rollback")){String id=WarmAbiHostR31.text(w.ro,"SELECT publication_id FROM r31_model_publication WHERE kind='WARM_FORK'");try(ModelPublicationR31.Plan saved=ModelPublicationR31.existing(w.ro,id)){RuntimeCoordinatorR26.Claim claim=w.claim;if(mode.equals("source")){SQLiteDatabase.scenario="CONTROLLED_SOURCE_REVISION";w.db.execSQL("UPDATE su1_source_clock SET generation=generation+1 WHERE singleton=1");}else{w.bind("warm-candidates",claim.fence+1);}SQLiteDatabase.scenario="NEW_WARM_REJECT_"+mode;refused=false;try{ModelPublicationR31.stageAndPublish(w.store,claim,saved);}catch(RuntimeException expected){refused=true;}need(refused,"OLD_SOURCE_OR_OWNER_REJECTED:"+mode);}need(n(w,"SELECT count(*) FROM r31_commit_receipt")==receipts,"OLD_PLAN_NO_RECEIPT_ADVANCE");}
            }
            if(mode.equals("cancel")){SQLiteDatabase.scenario="NEW_WARM_CANCEL";SQLiteDatabase.afterFrame=f->Thread.currentThread().interrupt();boolean refused=false;try{WarmCandidateR26.step(w.store,()->w.claim,new BudgetTokenSU1(60000,10000000,()->false));}catch(Exception expected){refused=true;}finally{SQLiteDatabase.afterFrame=null;Thread.interrupted();}need(refused,"CANCEL_OBSERVED");need(n(w,"SELECT count(*) FROM r26_warm_initialization")==0,"CANCEL_NO_CURRENT_PARTIAL");}
            if(resume){need(n(w,"SELECT count(*) FROM r31_model_publication WHERE kind='WARM_FORK' AND status='PREPARING'")==1,"DURABLE_PRIVATE_PLAN_SURVIVED_PROCESS_HALT");String parent=WarmAbiHostR31.text(w.ro,"SELECT hex(state) FROM r26_candidate WHERE campaign_id='OLD_WARM_PARENT'");Set<String> keep=new HashSet<>();try(Cursor c=w.ro.rawQuery("SELECT state FROM r26_candidate WHERE campaign_id='OLD_WARM_PARENT'",null)){need(c.moveToFirst(),"PARENT_EXISTS_AFTER_HALT");keep.add(CheckpointArtifactsR26.referenceHash(c.getBlob(0)));}long removed=CheckpointArtifactsR26.forStore(w.store).prune(keep,System.currentTimeMillis()+100000,0,100);need(removed>0,"ACTUAL_EXISTING_ARTIFACT_PRUNE_REMOVED_UNCOMMITTED_CHILD_FILES");need(parent.equals(WarmAbiHostR31.text(w.ro,"SELECT hex(state) FROM r26_candidate WHERE campaign_id='OLD_WARM_PARENT'")),"PARENT_REFERENCE_PRESERVED");}
            SQLiteDatabase.scenario="NEW_WARM_"+mode;if(mode.equals("diagnostic"))PublicationNativeHostR31.diagnostic("AFTER_COMMIT",()->{throw new IllegalStateException("CONTROLLED_WARM_POST_COMMIT_DIAGNOSTIC");});try{WarmCandidateR26.step(w.store,()->w.claim,new BudgetTokenSU1(60000,10000000,()->false));}finally{PublicationNativeHostR31.diagnostic(null,null);}SQLiteDatabase.afterFrame=null;invariant(w);long receipts=n(w,"SELECT count(*) FROM r31_commit_receipt");for(int i=0;i<100;i++)WarmCandidateR26.step(w.store,()->w.claim,new BudgetTokenSU1(60000,10000000,()->false));need(receipts==n(w,"SELECT count(*) FROM r31_commit_receipt"),"100_REPLAYS_NO_RECEIPT_OR_WORK_DUPLICATION");invariant(w);budgets(start);System.out.println("PASS "+WarmAbiHostR31.assertions+" ACTUAL_WARM_"+mode);
        }
    }
    static void closed(Path path)throws Exception{
        Files.deleteIfExists(path);try(WarmAbiHostR31.World w=new WarmAbiHostR31.World(path,"legacy-generation")){boolean refused=false;try{new ModelPublicationR31.Plan("UNKNOWN","ARBITRARY","source",0,-1,1);}catch(IllegalArgumentException expected){refused=true;}need(refused,"UNKNOWN_MAIN_KIND_REJECTED");try(ModelPublicationR31.Plan p=new ModelPublicationR31.Plan("BAD_ITEM","LEGACY","source",0,-1,1)){refused=false;try{p.put("WARM_META","not-legacy",1);}catch(IllegalArgumentException expected){refused=true;}need(refused,"CROSS_KIND_ITEM_REJECTED");refused=false;try{p.put("ARBITRARY_SQL","sql","DELETE FROM su2_model_genome");}catch(IllegalArgumentException expected){refused=true;}need(refused,"UNKNOWN_ITEM_KIND_REJECTED");}
        }
        Path valid=path.resolveSibling("closed-valid.db");Files.deleteIfExists(valid);try(PublicationNativeHostR31.World w=new PublicationNativeHostR31.World(valid,"legacy-generation")){w.legacyFixture();final boolean[] invoked={false};SQLiteDatabase.scenario="NEW_CLOSED_CALLBACK_COMPATIBILITY";ModelPublicationR31.stageAndPublish(w.store,w.claim,PublicationNativeHostR31.legacyPlan(w),(db,p)->{invoked[0]=true;db.execSQL("DELETE FROM su2_model_genome");});need(!invoked[0],"OLD_CALLBACK_NEVER_EXECUTED");PublicationNativeHostR31.invariants(w);need(WarmAbiHostR31.scalar(w.ro,"SELECT count(*) FROM su2_model_genome")==36,"CLOSED_LEGACY_PROJECTOR_ACTUALLY_RAN");}System.out.println("PASS "+WarmAbiHostR31.assertions+" CLOSED_KIND_DISPATCH_AND_CALLBACK_NEGATIVE");
    }
    public static void main(String[] args)throws Exception{Class.forName("org.sqlite.JDBC");Path path=Paths.get(args[1]);Files.createDirectories(path.getParent());if(args[0].equals("drain")){drain(path);return;}if(args[0].equals("closed")){closed(path);return;}warm(path,args[0]);}
